SELECT DISTINCT A.DIVISION_ID AS DIVISION_ID, C.DEPT_ID AS CODE     , CASE @langCd WHEN 'EN' THEN C.DEPT_NAME_EN           WHEN 'CN' THEN C.DEPT_NAME_CN           ELSE C.DEPT_NAME_KO       END AS NAME FROM SCM_MST_SITE_ITEM A    , SCM_MST_SSO_DEPT_INFO C WHERE 1=1 AND   A.DEPT_ID = C.DEPT_ID AND   A.DIVISION_ID IN (SELECT DISTINCT UNIT_ID                         FROM   SCM_ADM_USER_GR_UNIT_AUTH_MPG_M A                         WHERE  USER_ID = @sesUserId                         AND    UNIT_TP_CD = 'D') ORDER BY DIVISION_ID, NAME, CODE